package main
import "fmt"
macro_rules! twice {($value:expr)=>{func() int {value:=$value;return value+value}()};}
macro_rules! zero {()=>{int(0)};}
macro_rules! capture {($value:expr)=>{$value};}
func main(){
 fmt.Println(twice!(21))
 {type int string; value:=capture!(int("caller"));fmt.Printf("%T %s\n",zero!(),value)}
 {type int int64; value:=capture!(int(7));fmt.Printf("%T %T %d\n",zero!(),value,value)}
}

package main
import "fmt"
#[derive(Clone,Debug)]
type src struct{ N int }
#[derive(Clone,Debug)]
type Box struct{ Items [][]src }
func main(){
 original:=Box{Items:[][]src{{{N:3}}}}
 ordinary:=original
 ordinary.Items[0][0].N=4
 copied:=CloneBox(&original)
 copied.Items[0][0].N=9
 fmt.Println(DebugBox(&original))
 fmt.Println(DebugBox(&copied))
}

package main
macro_rules! invalid {($T:expr)=>{func() int {var value $T;_=value;return 0}()};}
func main(){_=invalid!(int)}

package main
import "fmt"
import s "github.com/goxide-lang/std/sum"
func Make()s.Option[int]{return s.Option[int]::Some(7)}
func Read(v s.Option[int])int{return match v{s.Option[int]::Some(n)=>n,s.Option[int]::None=>0}}
func Inferred()int{return match s.NewSome(8){s.Option[int]::Some(n)=>n,s.Option[int]::None=>0}}
func main(){fmt.Println(Read(Make()),Read(s.None[int]()),Inferred())}

package main
import "fmt"
import s "github.com/goxide-lang/std/sum"
func Next(v s.Result[int,error])s.Result[int,error]{n:=v?;return s.Result[int,error]::Ok(n+1)}
func Read(v s.Result[int,error])int{return match v{s.Result[int,error]::Ok(n)=>n,s.Result[int,error]::Err(_)=>-1}}
func main(){fmt.Println(Read(Next(s.NewOk[int,error](4))),Read(Next(s.NewErr[int,error](fmt.Errorf("bad")))))}

package main
import "fmt"
import s "github.com/goxide-lang/std/sum"
enum Mode{Idle,}
type Modes []Mode
type Envelope struct{Items map[string]Modes}
func Inspect(v s.Option[Envelope],seen *int){match v{s.Option[Envelope]::Some(_)=>{*seen+=1},s.Option[Envelope]::None=>{}}}
func rejected(v s.Option[Envelope],want string)(ok bool){seen:=0;defer func(){ok=fmt.Sprint(recover())==want && seen==0}();Inspect(v,&seen);return false}
func main(){
 good:=Envelope{Items:map[string]Modes{"ok":{Mode::Idle}}}
 seen:=0
 Inspect(s.NewSome(good),&seen)
 bad:=Envelope{Items:map[string]Modes{"bad":{nil}}}
 fmt.Println(seen,rejected(s.NewSome(bad),"goxide: invalid enum Mode"),rejected((*s.Some[Envelope])(nil),"goxide: invalid enum Option"))
}
